const $=s=>document.querySelector(s);
const view=$('#view'), nav=$('#nav'), toastEl=$('#toast');
const B=window.ArkforgeNative;
const state={boot:null,route:'home',op:'overview',selectedProject:null,lastImport:null,pendingBibleAttach:false,
 publicBibleSlug:'matthew',publicBibleChapter:1,publicBibleRedLetters:true,
 publicReaderMode:'page',publicReaderPage:1,publicReaderPerPage:8,publicReaderFont:20,
 publicReaderShowNumbers:true,publicReaderRows:[],publicReaderLabel:'',publicReaderSummary:'',readerTurnDirection:'next',viewerProjectId:'',viewerRelPath:''};
const CIRCUITS=[
 ['mywork','My Work'],['files','Files'],['games','Games'],['library','Library'],
 ['production','Production'],['engineering','Engineering'],['garden','Garden'],['farm','Farm Time'],
 ['cantus','Cantus Logs'],['kernel','Kernel'],['constructor','Constructor'],['systems','Systems']
];
const OPS=['Overview','New','Import','Search','Open','Inspect','Finish','Export','History','Verify','Restore','Help'];
const RECORD_TOOLS=[
 ['calendar','Calendar','Events, appointments and local planning'],
 ['map','Maps / Geo','Pins, coordinates and Android map handoff'],
 ['messages','Messages / Notes','Local messages and durable notes'],
 ['medical','Medical Organizer','Private local organizer records'],
 ['images','Images','Imported images and image records'],
 ['saved','Saved','Saved items and archive semantics'],
 ['artifact','Artifact Studio','Artifacts, requirements and digital evidence'],
 ['design','Design Studio','Design and blueprint records'],
 ['lifecycle','Lifecycle Registry','CONCEPT → SPECIFIED → MEASURED → MODELED → REVIEWED → PROTOTYPED → TESTED → QUALIFIED → RELEASED → ARCHIVED'],
 ['failures','Failure Taxonomy','Failures, review findings and recovery notes'],
 ['provenance','Provenance Index','Source, hash and evidence records'],
 ['materials','Material Canon','Materials, properties and references'],
 ['physics','Physics Vault','Calculations, models and references'],
 ['constraints','Constraint Graph','Constraints, dependencies and tradeoffs'],
 ['patents','Patent Vault','Patent and prior-art research records'],
 ['civis','CIVIS Gear','CIVIS Gear project records and imported evidence'],
 ['catalog','Catalog Zero','Catalog records; network sources stay explicit'],
 ['radio','Radio','Radio/directory records and Android URL handoff'],
 ['comms','Communications','Phone, SMS and email handoff'],
 ['archive','Archive','Archived record review and backup'],
 ['continuity','Continuity','Migration ledger, unresolved references, exact-byte evidence and promotion lock'],
 ['argus','Argus','Safe HTTPS intake with private-network blocking']
];
const CORE_NAV=[['home','Home'],['core','Unified Core'],['homebase','Home Base'],['bible','Scripture'],['library','Library'],['search','Search'],['constructor','Constructor'],['settings','Settings']];

function parse(s){try{return JSON.parse(s)}catch(e){return {ok:false,error:String(e)}}}
function call(name,...args){if(!B||typeof B[name]!=='function')return {ok:false,error:`Native bridge method ${name} unavailable`};try{return parse(B[name](...args))}catch(e){return {ok:false,error:String(e)}}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function metaObj(r){try{return JSON.parse(r?.meta_json||'{}')}catch(e){return {}}}

function routeCard(route,tag,title,description,icon='•'){
 return `<button type="button" class="card route-card" data-route-card="${esc(route)}"><div class="module-icon">${esc(icon)}</div><div class="tag">${esc(tag)}</div><h3>${esc(title)}</h3><p class="small muted">${esc(description)}</p></button>`;
}
function wireRouteCards(root=view){root.querySelectorAll('[data-route-card]').forEach(b=>b.onclick=()=>navigate(b.dataset.routeCard));}
function projectCards(projects){
 const a=projects||[];
 return `<div class="grid">${a.map(p=>`<article class="card"><div class="row"><div class="grow"><div class="tag">${esc(p.family||'project')} · ${esc(p.version||'')}</div><h3>${esc(p.name)}</h3></div><span class="state">${esc(p.status||'')}</span></div><p>${esc(p.description||'')}</p><div class="small muted">${esc(p.root_path||p.source_uri||'managed local project')}</div><div class="actions"><button data-project-run="${esc(p.id)}" class="primary">Open / Run</button><button data-project-list-files="${esc(p.id)}">Files</button></div></article>`).join('')||'<div class="card muted">No projects.</div>'}</div>`;
}
function wireProjectButtons(root=view){
 root.querySelectorAll('[data-project-run]').forEach(b=>b.onclick=()=>B.runProject(b.dataset.projectRun));
 root.querySelectorAll('[data-project-list-files]').forEach(b=>b.onclick=()=>showProjectFiles(b.dataset.projectListFiles));
}
function showProjectFiles(projectId){
 const p=call('project',projectId),r=call('projectFiles',projectId),files=r.files||[];
 view.innerHTML=sectionTitle(`Files — ${p.name||projectId}`,'Managed project files. Text/source formats can be previewed inside HeritageFaith; all supported files can be handed to Android.')+
 `<div class="actions"><button id="projectFilesBack">← Back</button></div><div class="card list">${files.map(f=>`<div class="item"><div class="row"><div class="grow"><b>${esc(f.name)}</b><div class="small muted">${esc(f.rel_path)} · ${Number(f.size||0).toLocaleString()} bytes</div></div><span class="state">${esc(f.kind||'file')}</span></div><div class="small mono muted">${esc(f.sha256||'')}</div><div class="actions"><button data-managed-preview="${esc(projectId)}" data-rel="${esc(f.rel_path)}">Preview text</button><button data-managed-open="${esc(projectId)}" data-rel="${esc(f.rel_path)}">Open externally</button></div></div>`).join('')||'<div class="muted">No managed files.</div>'}</div>`;
 $('#projectFilesBack').onclick=()=>render();
 view.querySelectorAll('[data-managed-open]').forEach(b=>b.onclick=()=>{const r=call('openProjectFile',b.dataset.managedOpen,b.dataset.rel);if(!r.ok)toast(r.error||'Could not open file',true)});
 view.querySelectorAll('[data-managed-preview]').forEach(b=>b.onclick=()=>navigate('viewer',`project=${encodeURIComponent(b.dataset.managedPreview)}&rel=${encodeURIComponent(b.dataset.rel)}`));
}

function pageLabel(m){const p=String(m?.page||'').trim();const e=String(m?.page_end||'').trim();return p?(e&&e!==p?`pp. ${esc(p)}–${esc(e)}`:`p. ${esc(p)}`):'page not set'}
function bibleRefKey(ref){return String(ref||'').trim().toLowerCase().replace(/[–—]/g,'-').replace(/\s+/g,' ')}
function bibleYear(y){const n=Number(y);if(!Number.isFinite(n))return String(y??'');if(n<0)return `${Math.abs(n)} BC`;if(n>0)return `${n} AD`;return 'c. 1 BC/AD boundary'}
function bibleLeafKey(page,ref,leaf){return `${String(page||'').trim()}|${bibleRefKey(ref)}|${Number(leaf)||0}`}


function loadBibleReaderPrefs(){
 try{
  const p=JSON.parse(localStorage.getItem('heritagefaith.bible.reader.settings.v1')||'{}');
  if(['page','scroll'].includes(p.mode))state.publicReaderMode=p.mode;
  if([4,6,8,10,12,16].includes(Number(p.perPage)))state.publicReaderPerPage=Number(p.perPage);
  if([17,18,20,22,24,28,32].includes(Number(p.font)))state.publicReaderFont=Number(p.font);
  if(typeof p.showNumbers==='boolean')state.publicReaderShowNumbers=p.showNumbers;
 }catch(e){}
}
function saveBibleReaderPrefs(){
 try{localStorage.setItem('heritagefaith.bible.reader.settings.v1',JSON.stringify({
  mode:state.publicReaderMode,perPage:state.publicReaderPerPage,font:state.publicReaderFont,showNumbers:state.publicReaderShowNumbers
 }))}catch(e){}
}
loadBibleReaderPrefs();

function bookIndexFromLibrary(records,projects){
 const byProject=new Map((projects||[]).map(p=>[p.id,p])),seenSha=new Map(),rows=[];
 for(const rec of records||[]){
  const m=metaObj(rec);if(!m.project_id)continue;
  const path=String(m.relative_path||m.filename||rec.title||'').replace(/\\/g,'/');
  const parts=path.split('/').filter(Boolean);
  const filename=parts.length?parts[parts.length-1]:rec.title;
  const dot=filename.lastIndexOf('.');
  const format=dot>=0?filename.slice(dot+1).toLowerCase():'';
  const inferredAuthor=parts.length>1?parts[0]:'Unsorted / unknown author';
  const title=(m.title||rec.title||filename).replace(/\.[^.]+$/,'').trim();
  const author=(m.author||inferredAuthor||'').trim()||'Unsorted / unknown author';
  const sha=String(m.sha256||'').trim();
  const project=byProject.get(m.project_id)||{};
  const row={record:rec,meta:m,project,title,author,format,sha,
   sourceFolder:m.source_folder||'',relativePath:path,bytes:Number(m.bytes||0),
   imported:rec.updated_at||rec.created_at||'',duplicate:false};
  if(sha){if(seenSha.has(sha)){row.duplicate=true;seenSha.get(sha).duplicate=true}else seenSha.set(sha,row)}
  rows.push(row);
 }
 return rows.sort((a,b)=>a.author.localeCompare(b.author)||a.title.localeCompare(b.title));
}

function parseBibleRef(ref){
 const s=String(ref||'').trim().replace(/[–—]/g,'-');
 const m=s.match(/^(.+?)\s+(\d+)(?::(\d+))?/);
 return m?{book:m[1].trim(),chapter:Number(m[2]),verse:m[3]?Number(m[3]):null}:null;
}
function firstBibleRef(refs){return String(refs||'').split(';')[0].trim();}
function openBibleReference(ref){const r=firstBibleRef(ref);location.hash=`#bible?ref=${encodeURIComponent(r)}`;}
function openStudyReference(ref,mode='logic'){const r=firstBibleRef(ref);location.hash=`#study?ref=${encodeURIComponent(r)}&mode=${encodeURIComponent(mode)}`;}
function sevenLeavesForReference(ref){
 const pack=call('bibleAtlasSpec'),defs=(pack.atlas?.seven_leaves||[]);
 const all=call('records','bible_commentary_leaf',false,10000).records||[];
 const byLeaf=new Map();for(const rec of all){const m=metaObj(rec);if(bibleRefKey(m.scripture_reference)===bibleRefKey(ref)&&!String(m.page||'').trim())byLeaf.set(Number(m.leaf),rec)}
 return {defs,byLeaf};
}
function openSevenLeavesDialog(ref){
 const dlg=$('#sevenLeavesDialog'),body=$('#sevenLeavesBody');if(!dlg||!body)return;
 const {defs,byLeaf}=sevenLeavesForReference(ref);$('#sevenLeavesTitle').textContent=ref;$('#sevenLeavesSubtitle').textContent='Seven expandable research categories. Saving a leaf creates a local study record; Scripture itself is never edited.';
 body.innerHTML=defs.map(d=>{const rec=byLeaf.get(Number(d.leaf)),m=rec?metaObj(rec):{};return `<section class="leaf-editor"><div class="row"><div class="grow"><div class="tag">LEAF ${esc(d.leaf)}</div><h3>${esc(d.name)}</h3><div class="small muted">${esc(d.rule||'')}</div></div><span class="state ${rec?'NATIVE':'IMPORT_REQUIRED'}">${rec?'STARTED':'EMPTY'}</span></div><div class="small">Study questions: ${(d.questions||[]).map(q=>esc(q)).join(' · ')}</div><label>Working commentary<textarea data-leaf-body="${esc(d.leaf)}">${esc(rec?.body||'')}</textarea></label><label>Source IDs / labels<input data-leaf-sources="${esc(d.leaf)}" value="${esc((Array.isArray(m.source_ids)?m.source_ids:[]).join(', '))}" placeholder="e.g. SCRIPTURE, CCC-1324, Augustine-Homily-1"></label><label>Uncertainty / disagreement<input data-leaf-uncertainty="${esc(d.leaf)}" value="${esc(m.uncertainty||'OPEN')}" placeholder="OPEN / LOW / DISPUTED / RESOLVED"></label><button type="button" class="primary" data-save-leaf="${esc(d.leaf)}">Save Leaf ${esc(d.leaf)}</button></section>`}).join('');
 body.querySelectorAll('[data-save-leaf]').forEach(btn=>btn.onclick=()=>{const n=Number(btn.dataset.saveLeaf),def=defs.find(x=>Number(x.leaf)===n),old=byLeaf.get(n);const text=body.querySelector(`[data-leaf-body="${n}"]`).value.trim();const ids=body.querySelector(`[data-leaf-sources="${n}"]`).value.split(',').map(x=>x.trim()).filter(Boolean);const uncertainty=body.querySelector(`[data-leaf-uncertainty="${n}"]`).value.trim()||'OPEN';const meta={book_id:'arkforge-public-odr',page:'',scripture_reference:ref,leaf:n,leaf_name:def?.name||`Leaf ${n}`,status:ids.length>=3?'SOURCE_TRIANGULATION_READY':(text?'IN_PROGRESS':'RESEARCH_REQUIRED'),required_source_classes:def?.required_source_classes||[],source_ids:[...new Set(ids)],uncertainty,rule:def?.rule||'',study_role:'research_curator'};let rr;if(old)rr=call('updateRecord',old.id,old.title,text,JSON.stringify(meta));else rr=call('addRecord','bible_commentary_leaf',`${ref} · Leaf ${n} — ${def?.name||''}`,text,JSON.stringify(meta));toast(rr.ok?`Leaf ${n} saved locally`:rr.error||'Save failed',!rr.ok);if(rr.ok)openSevenLeavesDialog(ref)});
 dlg.showModal();
}

function publicBibleRelated(starter,rows){
 const text=(rows||[]).map(v=>v.text||'').join(' ').toLowerCase();
 const match=(arr)=>((arr||[]).filter(x=>{const n=String(x.name||'').toLowerCase();return n.length>=3&&text.includes(n)}).slice(0,12));
 const persons=match(starter.persons),places=match(starter.places),objects=match(starter.objects),groups=match(starter.people_groups);
 const names=new Set(persons.map(x=>x.name));
 const timeline=(starter.timeline||[]).filter(x=>(x.related_people||[]).some(n=>names.has(n))).slice(0,10);
 return {persons,places,objects,groups,timeline};
}
function renderPublicBibleRows(rows,label,starter,redByRef,summary=''){
 const box=$('#publicBibleResults'),ctx=$('#publicBibleContext');if(!box)return;
 state.publicReaderRows=rows||[];state.publicReaderLabel=label||'';state.publicReaderSummary=summary||'';
 const j=window.ARKFORGE_JESUS_STUDY||{};const speechRefs=[];for(const group of [j.timeline||[],j.parables||[],j.miracles||[],j.teachings||[]])for(const x of group)for(const raw of String(x.refs||'').split(';')){const a=parseBibleRef(raw.trim());if(a&&a.verse)speechRefs.push({book:a.book.toLowerCase(),chapter:a.chapter,verse:a.verse,title:x.title})}
 const target=bibleRefKey(state.publicBibleTargetRef||'');
 const mode=state.publicReaderMode||'page',per=Math.max(1,Number(state.publicReaderPerPage)||8);
 let totalPages=mode==='page'?Math.max(1,Math.ceil((rows||[]).length/per)):1;
 if(target&&mode==='page'){const ti=(rows||[]).findIndex(v=>bibleRefKey(`${v.book} ${v.chapter}:${v.verse}`)===target);if(ti>=0)state.publicReaderPage=Math.floor(ti/per)+1}
 state.publicReaderPage=Math.min(totalPages,Math.max(1,Number(state.publicReaderPage)||1));
 const visible=mode==='page'?(rows||[]).slice((state.publicReaderPage-1)*per,state.publicReaderPage*per):(rows||[]);
 const verseHtml=visible.map(v=>{const ref=`${v.book} ${v.chapter}:${v.verse}`,key=bibleRefKey(ref),red=state.publicBibleRedLetters&&redByRef.has(key);const notes=Array.isArray(v.notes)?v.notes:[],refs=Array.isArray(v.cross_refs)?v.cross_refs:[];const speechHint=speechRefs.find(s=>s.book===String(v.book).toLowerCase()&&s.chapter===Number(v.chapter)&&s.verse===Number(v.verse));return `<article class="bible-verse ${red?'red-letter':''} ${target===key?'target-verse':''}" data-bible-ref-key="${esc(key)}"><div class="verse-ref ${state.publicReaderShowNumbers?'':'reader-hide-number'}">${esc(ref)} ${speechHint?'<span class="jesus-speech-hint">JESUS STUDY</span>':''}</div><div class="verse-text" style="font-size:${Number(state.publicReaderFont)||20}px">${state.publicReaderShowNumbers?`<sup class="inline-verse-number">${esc(v.verse)}</sup> `:''}${esc(v.text)}</div>${notes.length?`<details><summary>Footnotes (${notes.length})</summary><div class="small">${notes.map(n=>`<p><b>${esc(n.label||'•')}</b> ${esc(n.text||'')}</p>`).join('')}</div></details>`:''}${refs.length?`<div class="small muted">Cross references: ${refs.map(r=>esc(r.text||r)).join(' · ')}</div>`:''}<div class="actions"><button class="mini" data-public-note-ref="${esc(ref)}">Note</button><button class="mini" data-public-question-ref="${esc(ref)}">Question</button><button class="mini" data-public-leaves-ref="${esc(ref)}">7 Leaves</button><button class="mini" data-public-study-ref="${esc(ref)}">Logic Path</button><button class="mini" data-public-red-ref="${esc(ref)}">${redByRef.has(key)?'Red-letter record':'Mark Jesus words'}</button></div></article>`}).join('')||'<div class="muted">No verses returned.</div>';
 const pager=mode==='page'?`<div class="reader-page-nav"><button id="readerPagePrev" ${state.publicReaderPage<=1?'disabled':''}>← Turn back</button><div class="reader-page-number"><b>Page ${state.publicReaderPage}</b> of ${totalPages}<div class="small muted">${esc(label)}</div></div><button id="readerPageNext" ${state.publicReaderPage>=totalPages?'disabled':''}>Turn page →</button></div>`:'';
 box.innerHTML=`<section class="scripture-paper-page ${mode==='page'?'paged-reader':'scroll-reader'} ${state.readerTurnDirection==='prev'?'page-turn-prev':'page-turn-next'}"><div class="reader-running-head"><span>${esc(label)}</span><span>${mode==='page'?`Chapter page ${state.publicReaderPage}/${totalPages}`:'Scroll reading'}</span></div>${summary?`<div class="notice"><b>Chapter summary from source edition</b><div class="small">${esc(summary)}</div></div>`:''}${verseHtml}<div class="reader-running-foot">${mode==='page'?`HeritageFaith · ${esc(label)} · ${state.publicReaderPage}`:'HeritageFaith · Scripture'}</div></section>${pager}`;
 const rel=publicBibleRelated(starter,visible||[]);if(ctx)ctx.innerHTML=`<div class="tag">STUDY CONTEXT</div><h3>People, places & timeline on this ${mode==='page'?'page':'chapter'}</h3>${[['People',rel.persons],['Peoples',rel.groups],['Places',rel.places],['Things',rel.objects]].map(([k,a])=>a.length?`<div class="context-group"><b>${k}</b><div class="chip-cloud">${a.map(x=>`<span>${esc(x.name)}</span>`).join('')}</div></div>`:'').join('')}${rel.timeline.length?`<div class="context-group"><b>Timeline</b>${rel.timeline.map(x=>`<div class="small">${esc(bibleYear(x.start_year))}: ${esc(x.label)}</div>`).join('')}</div>`:''}<div class="small muted">Atlas matches are navigation hints, not proof of identity or chronology.</div>`;
 box.querySelectorAll('[data-public-note-ref]').forEach(b=>b.onclick=()=>{const body=prompt('Your note for '+b.dataset.publicNoteRef);if(!body)return;const r=call('addRecord','bible_note',b.dataset.publicNoteRef,body,JSON.stringify({book_id:'arkforge-public-odr',scripture_reference:b.dataset.publicNoteRef,note_type:'verse_note'}));toast(r.ok?'Verse note saved':r.error||'Save failed',!r.ok)});
 box.querySelectorAll('[data-public-question-ref]').forEach(b=>b.onclick=()=>{const q=prompt('Your question for '+b.dataset.publicQuestionRef);if(!q)return;const r=call('addRecord','bible_question',b.dataset.publicQuestionRef,q,JSON.stringify({book_id:'arkforge-public-odr',scripture_reference:b.dataset.publicQuestionRef,status:'OPEN'}));toast(r.ok?'Question saved':r.error||'Save failed',!r.ok)});
 box.querySelectorAll('[data-public-leaves-ref]').forEach(b=>b.onclick=()=>openSevenLeavesDialog(b.dataset.publicLeavesRef));
 box.querySelectorAll('[data-public-study-ref]').forEach(b=>b.onclick=()=>openStudyReference(b.dataset.publicStudyRef,'logic'));
 box.querySelectorAll('[data-public-red-ref]').forEach(b=>b.onclick=()=>{const ref=b.dataset.publicRedRef;if(redByRef.has(bibleRefKey(ref))){toast('A red-letter record already exists for '+ref);return}const authority=prompt('Source / authority for marking this verse as Jesus’ spoken words');if(!authority)return;const note=prompt('Dialogue-boundary note (optional)')||'';const rr=call('addRecord','bible_red_letter',ref,note||'Whole verse marked for the red-letter display layer.',JSON.stringify({scripture_reference:ref,source_authority:authority,confidence:'REVIEWED',scope:'whole_verse',display_only:true}));toast(rr.ok?'Red-letter annotation added':rr.error||'Could not add annotation',!rr.ok);if(rr.ok)renderBibleWorkspace()});
 const prev=$('#readerPagePrev'),next=$('#readerPageNext');
 if(prev)prev.onclick=()=>{state.readerTurnDirection='prev';state.publicReaderPage=Math.max(1,state.publicReaderPage-1);renderPublicBibleRows(rows,label,starter,redByRef,summary)};
 if(next)next.onclick=()=>{state.readerTurnDirection='next';state.publicReaderPage=Math.min(totalPages,state.publicReaderPage+1);renderPublicBibleRows(rows,label,starter,redByRef,summary)};
 if(mode==='page'){
  let x0=null;box.ontouchstart=e=>{x0=e.touches?.[0]?.clientX??null};box.ontouchend=e=>{if(x0==null)return;const x1=e.changedTouches?.[0]?.clientX??x0,dx=x1-x0;x0=null;if(Math.abs(dx)<70)return;if(dx<0&&state.publicReaderPage<totalPages){state.readerTurnDirection='next';state.publicReaderPage++;renderPublicBibleRows(rows,label,starter,redByRef,summary)}else if(dx>0&&state.publicReaderPage>1){state.readerTurnDirection='prev';state.publicReaderPage--;renderPublicBibleRows(rows,label,starter,redByRef,summary)}};
 }
 if(target){const el=box.querySelector(`[data-bible-ref-key="${CSS.escape(target)}"]`);if(el)setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'center'}),80)}
}

function toast(msg,bad=false){toastEl.textContent=msg;toastEl.classList.add('show');toastEl.style.borderColor=bad?'#744':'';clearTimeout(toast._t);toast._t=setTimeout(()=>toastEl.classList.remove('show'),3500)}
function setStatus(){const s=state.boot?.stats||{};$('#runtimeStatus').textContent=`Local-first · SQLite ${s.db_integrity||'…'} · ${s.records||0} study records`;}
function navigate(route,op='overview'){
 if(String(op).includes('=')&&String(op).includes('&')){location.hash=`#${encodeURIComponent(route)}?${op}`;return}
 location.hash=`#${encodeURIComponent(route)}?op=${encodeURIComponent(String(op).toLowerCase())}`;
}
function routeFromHash(){let raw=location.hash.replace(/^#/,'')||'home';let [r,q='']=raw.split('?');r=decodeURIComponent(r||'home');let p=new URLSearchParams(q);return {route:r,op:p.get('op')||'overview'};}
function renderNav(){nav.innerHTML=CORE_NAV.map(([id,label])=>`<button type="button" data-nav="${esc(id)}" class="${state.route===id?'active':''}">${esc(label)}</button>`).join('');nav.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.nav)));}
function refreshBoot(){const b=call('bootstrap');if(b.ok){state.boot=b;setStatus()}else toast(b.error||'Bootstrap failed',true);}
function operationBanner(){if(state.op==='overview'||state.route==='home'||RECORD_TOOLS.some(x=>x[0]===state.route))return '';const label=OPS.find(x=>x.toLowerCase()===state.op)||state.op;return `<div class="notice"><div class="row"><div class="grow"><b>144 Circuit operation · ${esc(label)}</b><div class="small muted">Deep link: ${esc(state.route)} / ${esc(state.op)}. The button below routes this operation through the native HeritageFaith workflow.</div></div><button data-action="op-execute" class="primary">Run ${esc(label)}</button></div></div>`}
function sectionTitle(title,subtitle=''){return `<h1>${esc(title)}</h1>${subtitle?`<p class="muted">${esc(subtitle)}</p>`:''}${operationBanner()}`}
function actionButton(label,action,primary=false){return `<button type="button" class="${primary?'primary':''}" data-action="${esc(action)}">${esc(label)}</button>`}
function wireActions(root=view){root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset.action,b)));}

function render(){let r=routeFromHash();state.route=r.route;state.op=r.op;renderNav();
  switch(state.route){
    case 'home':return renderHome();
    case 'core':return renderUnifiedCore();
    case 'homebase':return renderHomeBase();
    case 'mywork':return renderMyWork();
    case 'files':return renderFiles();
    case 'games':return renderGames();
    case 'production':return renderProduction();
    case 'engineering':return renderEngineering();
    case 'garden':return renderGarden();
    case 'farm':return renderFarm();
    case 'cantus':return renderCantus();
    case 'kernel':return renderKernel();
    case 'systems':return renderSystems();
    case 'continuity':return renderContinuity();
    case 'phoneintake':return renderPhoneIntake();
    case 'search':return renderGlobalSearch();
    case 'viewer':return renderUniversalViewer();
    case 'routeatlas':return renderRouteAtlas();
    case 'bible':return renderBibleWorkspace();
    case 'understand':return renderUnderstand();
    case 'live':return renderLive();
    case 'alexandria':return renderAlexandria();
    case 'humanity':return renderHumanity();
    case 'creationmap':return renderCreationMap();
    case 'cantuslab':return renderCantusLab();
    case 'runes':return renderRunes();
    case 'meaningcourse':return renderMeaningCourse();
    case 'occult':return renderOccultResearch();
    case 'patents':return renderPatents();
    case 'technology':return renderTechnology();
    case 'familygifts':return renderFamilyGifts();
    case 'techniques':return renderHumanTechniques();
    case 'constructor':return renderConstructor();
    case 'settings':return renderSettings();
    case 'jesus':return renderJesusCenter();
    case 'study':return renderStudyLab();
    case 'worksheets':return renderFaithWorksheets();
    case 'church':return renderLivingChurch();
    case 'tradition':return renderLivingTradition();
    case 'ancestors':return renderAncestors();
    case 'library':return renderLibrary();
    case 'notes':return renderMyNotes();
    default:{
      const tool=RECORD_TOOLS.find(x=>x[0]===state.route);
      if(tool)return renderGenericTool(tool[0],tool[1],tool[2]);
      return renderNotFound();
    }
  }
}



