 const notes=(call('records','bible_note',false,2000).records||[]).sort((a,b)=>(Number(metaObj(a).page)||999999)-(Number(metaObj(b).page)||999999));
 const questions=call('records','bible_question',false,2000).records||[];
 const resolutions=call('records','bible_resolution',false,2000).records||[];
 const sessions=call('records','church_group_session',false,2000).records||[];
 const attachments=call('records','bible_digital_attachment',false,250).records||[];
 const commentary=call('records','bible_commentary_leaf',false,10000).records||[];
