 const corpora=(call('bibleCorpora').corpora||[]);
 const publicSource=call('publicBibleSource'),publicStatus=call('publicBibleStatus');
 const publicBooks=publicSource.books||[];
 const bibleParams=new URLSearchParams(location.hash.split('?')[1]||'');const requestedRef=bibleParams.get('ref')||'';if(requestedRef){const pr=parseBibleRef(requestedRef);if(pr){const match=publicBooks.find(b=>String(b.name).toLowerCase()===pr.book.toLowerCase());if(match){state.publicBibleSlug=match.slug;state.publicBibleChapter=pr.chapter;state.publicBibleTargetRef=pr.verse?`${match.name} ${pr.chapter}:${pr.verse}`:'';}}}
 const allProjects=call('projects').projects||[];
 const resByQ={};for(const r of resolutions){const m=metaObj(r);if(m.question_id)(resByQ[m.question_id]||(resByQ[m.question_id]=[])).push(r)}
 const redByRef=new Map();for(const r of redLetters){const m=metaObj(r),k=bibleRefKey(m.scripture_reference||r.title);if(k)redByRef.set(k,r)}
 const leafMap=new Map();for(const r of commentary){const m=metaObj(r);leafMap.set(bibleLeafKey(m.page,m.scripture_reference,m.leaf),r)}
 const sourceById=new Map(sources.map(x=>[x.id,x]));
 if(state.bibleRedLetters===undefined)state.bibleRedLetters=true;
 if(!state.bibleCorpusId&&corpora.length)state.bibleCorpusId=corpora[0].id;
 if(!state.bibleBook)state.bibleBook='Matthew';if(!state.bibleChapter)state.bibleChapter=1;
 const sourcePolicy=sourceData.policy||{};
 const commentaryCards=commentary.slice().sort((a,b)=>{const ma=metaObj(a),mb=metaObj(b);return (Number(ma.page)||999999)-(Number(mb.page)||999999)||(Number(ma.leaf)||0)-(Number(mb.leaf)||0)}).map(r=>{const m=metaObj(r),ids=Array.isArray(m.source_ids)?m.source_ids:[];return `<div class="item commentary-leaf"><div class="row"><div class="grow"><b>${pageLabel(m)} · Leaf ${esc(m.leaf||'?')} — ${esc(m.leaf_name||r.title)}</b><div class="small muted">${esc(m.scripture_reference||'reference not mapped')} · ${esc(m.status||'RESEARCH_REQUIRED')}</div></div><span class="state ${ids.length>=3?'NATIVE':'IMPORT_REQUIRED'}">${ids.length} SOURCE${ids.length===1?'':'S'}</span></div><p>${esc(r.body)}</p><div class="small"><b>Citations:</b> ${ids.length?ids.map(id=>esc(sourceById.get(id)?.name||id)).join(' · '):'none recorded yet'}</div><div class="small muted">Required classes: ${esc((m.required_source_classes||[]).join(', ')||'not set')} · uncertainty: ${esc(m.uncertainty||'OPEN')}</div><div class="actions"><button data-leaf-add-source="${esc(r.id)}" data-current-sources="${esc(JSON.stringify(ids))}" data-leaf-meta="${esc(r.meta_json||'{}')}">Add / edit source IDs</button><button data-edit-record="${esc(r.id)}" data-type="bible_commentary_leaf" data-title="${esc(r.title)}" data-body="${esc(r.body)}" data-meta="${esc(r.meta_json||'{}')}">Write commentary</button><button data-archive-record="${esc(r.id)}" data-archived="0">Archive</button></div></div>`}).join('');
 const bookRows=books.map(b=>`<tr><td>${b.order}</td><td><b>${esc(b.canonical_name)}</b><div class="small muted">${esc(b.genre||'')}</div></td><td>${esc(b.kjv_name||'—')}</td><td>${esc(b.douay_rheims_name||'—')}</td><td>${esc(b.original_or_traditional_name||'—')}</td><td>${esc(b.name_meaning||'—')}${b.notes?`<div class="small muted">${esc(b.notes)}</div>`:''}</td></tr>`).join('');
