 const groupRows=(starter.people_groups||[]).map(x=>`<div class="item"><b>${esc(x.name)}</b><div class="small muted">${esc(x.period||'')}</div><p>${esc(x.note||'')}</p></div>`).join('');
 const placeRows=(starter.places||[]).map(x=>`<div class="item"><div class="row"><div class="grow"><b>${esc(x.name)}</b><div class="small muted">${esc(x.confidence||'')} · ${Number(x.lat).toFixed(4)}, ${Number(x.lon).toFixed(4)}</div></div><button data-bible-map-place="${esc(x.name)}" data-lat="${x.lat}" data-lon="${x.lon}">Map</button></div><p>${esc(x.note||'')}</p></div>`).join('');
 const objectRows=(starter.objects||[]).map(x=>`<div class="item"><div class="row"><b class="grow">${esc(x.name)}</b><span class="state">${esc(x.type||'thing')}</span></div><p>${esc(x.note||'')}</p></div>`).join('');
 const timelineRows=(starter.timeline||[]).slice().sort((a,b)=>(Number(a.start_year)||0)-(Number(b.start_year)||0)).map(x=>`<div class="timeline-event"><div class="timeline-year">${esc(bibleYear(x.start_year))}${x.end_year!==undefined&&x.end_year!==x.start_year?` – ${esc(bibleYear(x.end_year))}`:''}</div><div class="grow"><b>${esc(x.label)}</b><div class="small muted">${esc(x.precision||'')} · ${esc(x.confidence||'')}</div><div class="small">${esc(x.note||'')}</div>${x.related_people?`<div class="small muted">People: ${esc(x.related_people.join(', '))}</div>`:''}</div></div>`).join('');
 const sourceRows=sources.map(x=>`<div class="item"><div class="row"><div class="grow"><b>${esc(x.name)}</b><div class="small muted">${esc(x.class)} · ${esc(x.license||'license/terms must be checked')}</div></div>${x.url?`<button data-source-url="${esc(x.url)}">Open source</button>`:''}</div><div class="small">ID: <code>${esc(x.id)}</code></div><p>${esc(x.use||'')}</p></div>`).join('');
 const corpusRows=corpora.map(c=>`<div class="item"><div class="row"><div class="grow"><b>${esc(c.title)}</b><div class="small muted">${esc(c.translation||'')} · ${Number(c.verse_count||0).toLocaleString()} verses · ${Number(c.public_domain||0)?'PUBLIC DOMAIN':'RIGHTS / LICENSE REVIEW'}</div></div><button data-select-corpus="${esc(c.id)}">Use in reader</button></div><div class="small mono muted">SHA ${esc((c.sha256||'').slice(0,32))}${c.sha256?'…':''}</div><div class="small muted">${esc(c.license||'')}</div></div>`).join('');
 const redRows=redLetters.map(r=>{const m=metaObj(r);return `<div class="item"><div class="row"><b class="grow red-letter-label">${esc(m.scripture_reference||r.title)}</b><span class="state">${esc(m.confidence||'REVIEWED')}</span></div><div class="small"><b>Authority/source:</b> ${esc(m.source_authority||'not recorded')}</div><p>${esc(r.body||'Whole verse marked as words spoken by Jesus for display purposes.')}</p><div class="actions"><button data-edit-record="${esc(r.id)}" data-type="bible_red_letter" data-title="${esc(r.title)}" data-body="${esc(r.body)}" data-meta="${esc(r.meta_json||'{}')}">Edit</button><button data-archive-record="${esc(r.id)}" data-archived="0">Archive</button></div></div>`}).join('');
 view.innerHTML=sectionTitle('Scripture Context Atlas','A 73-book rights-cleared Catholic Scripture foundation with seven-leaf commentary, people, peoples, places, objects, maps, timelines, questions and church-group study.')+
 `<div class="bible-hero card"><div class="grow"><div class="tag">HERITAGEFAITH · SCRIPTURE · CONTEXT ATLAS</div><h2>Scripture with a Living Study Layer</h2><p class="muted">Original Douay-Rheims foundation · local notes · Seven Commentary Leaves · people · places · timelines · Church study</p><p><b>Jesus remains the center.</b> HeritageFaith organizes references, questions, maps, timelines and source-labeled research; the study layer does not replace Scripture or Church teaching.</p><div class="notice"><b>Source boundary</b><div class="small">${esc(atlas.exact_edition_boundary||'Rights-cleared Scripture and customer-selected local documents remain separate source layers.')}</div></div><div class="actions"><button id="attachBibleDigital" class="primary">Import my study document</button><button id="printBibleWorkspace">Print / save workspace</button><button id="backLibrary">← Library</button></div></div></div>
 <div class="grid bible-metrics"><div class="card"><div class="tag">BOOK INDEX</div><div class="metric">${books.length}</div><div class="small muted">Catholic canon entries with KJV / Douay names + definitions</div></div><div class="card"><div class="tag">COMMENTARY LEAVES</div><div class="metric">${commentary.length}</div><div class="small muted">Seven research leaves can grow from every Scripture reference</div></div><div class="card"><div class="tag">PUBLIC-DOMAIN CORPORA</div><div class="metric">${corpora.length}</div><div class="small muted">Searchable KJV / Douay or other licensed text imports</div></div><div class="card"><div class="tag">RED-LETTER MARKS</div><div class="metric">${redLetters.length}</div><div class="small muted">Toggleable annotations; source Bible never recolored</div></div></div>
 <section class="public-scripture-shell card"><div class="row"><div class="grow"><div class="tag">BUILT-IN CATHOLIC SCRIPTURE FOUNDATION</div><h2>Original Douay-Rheims · 73-Book Reader</h2><p class="muted">1582 New Testament · 1609–1610 Old Testament · CC0/public-domain source repository. This is the historic Original Douay-Rheims, not the later Challoner revision and not the copyrighted Ignatius RSV-2CE.</p></div><span class="state ${publicStatus.complete?'NATIVE':'IMPORT_REQUIRED'}">${publicStatus.complete?'OFFLINE READY':esc(publicStatus.state||'NOT INSTALLED')}</span></div>
 <div class="grid scripture-install-grid"><div><div class="progress-track"><span id="publicBibleProgress" style="width:${Math.round(100*Number(publicStatus.installed_books||0)/73)}%"></span></div><div id="publicBibleStatusText" class="small muted">${Number(publicStatus.installed_books||0)} / 73 canonical books cached · ${Number(publicStatus.bytes||0).toLocaleString()} bytes</div><div class="actions"><button id="installPublicBible" class="primary">${publicStatus.complete?'Verify / resume Scripture install':'Install 73-book Scripture'}</button><button id="publicBibleSourceButton">Source & rights</button></div></div><div class="notice"><b>Source preservation</b><div class="small">The downloaded CC0 JSON is cached in app-private storage. HeritageFaith renders it without rewriting the source. User notes, study commentary, and red-letter records are separate layers.</div></div></div>
 <form id="publicBibleReaderForm" class="form public-reader-controls"><label>Book<select id="publicReaderBook">${publicBooks.map(b=>`<option value="${esc(b.slug)}" ${b.slug===state.publicBibleSlug?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label>Chapter<input id="publicReaderChapter" type="number" min="1" value="${Number(state.publicBibleChapter)||1}"></label><label>Reading mode<select id="publicReaderMode"><option value="page" ${state.publicReaderMode==='page'?'selected':''}>Page turning</option><option value="scroll" ${state.publicReaderMode==='scroll'?'selected':''}>Continuous scroll</option></select></label><label>Verses per page<select id="publicReaderPerPage">${[4,6,8,10,12,16].map(n=>`<option value="${n}" ${Number(state.publicReaderPerPage)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Text size<select id="publicReaderFont">${[17,18,20,22,24,28,32].map(n=>`<option value="${n}" ${Number(state.publicReaderFont)===n?'selected':''}>${n}px</option>`).join('')}</select></label><label class="check"><input id="publicReaderNumbers" type="checkbox" ${state.publicReaderShowNumbers?'checked':''}> Verse numbering</label><label class="check"><input id="publicReaderRed" type="checkbox" ${state.publicBibleRedLetters?'checked':''}> Red-letter overlay</label><div class="actions"><button type="button" id="publicPrevChapter">← Previous chapter</button><button class="primary">Open chapter</button><button type="button" id="publicNextChapter">Next chapter →</button></div></form>
 <form id="publicBibleSearchForm" class="form inline-search"><label>Search installed Scripture<input id="publicBibleSearchQuery" placeholder="mercy, Jerusalem, bread of life…"></label><button>Search</button></form>
 <div class="public-reader-layout"><div id="publicBibleResults" class="bible-reader-results"><div class="muted">${publicStatus.complete?'Choose a book and chapter.':'Install the free CC0 Scripture foundation once, then the full 73-book reader works offline.'}</div></div><aside id="publicBibleContext" class="card study-context"><div class="tag">STUDY CONTEXT</div><p class="small muted">After a chapter opens, HeritageFaith surfaces matching people, peoples, places, things and timeline records from the Atlas.</p></aside></div></section>
 <details open><summary><b>Seven-Leaf Commentary</b></summary><div class="notice"><b>Seven leaves per Scripture reference</b><div class="small">${esc(atlas.page_model||'Each Scripture reference can own seven expandable commentary leaves.')}</div><div class="small">Finished commentary target: at least ${esc(sourcePolicy.minimum_commentary_sources||3)} independent source families where available. Disagreements remain visible.</div></div><div class="seven-leaf-grid">${leaves.map(l=>`<div class="card commentary-leaf"><div class="leaf-number">${l.leaf}</div><h3>${esc(l.name)}</h3><ul>${(l.questions||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ul><div class="small muted">Sources: ${esc((l.required_source_classes||[]).join(', '))}</div><div class="small"><b>Rule:</b> ${esc(l.rule||'')}</div></div>`).join('')}</div><div class="split" style="margin-top:12px"><div class="card"><form id="plantSevenLeaves" class="form"><label>Source page (optional, for an imported personal document)<input id="leafPage" inputmode="numeric" placeholder="optional"></label><label>Scripture reference / passage range<input id="leafRef" required placeholder="e.g. John 8:1–20"></label><button class="primary">Plant all 7 commentary leaves</button></form><p class="small muted">This plants research structures, not invented conclusions. Each leaf begins RESEARCH_REQUIRED and can expand without a hard page limit.</p></div><div class="card"><div class="tag">CURRENT RESEARCH</div><div class="metric">${commentary.length}</div><div class="small muted">Use source IDs from the Source Registry below. Three families is the normal completion target, where available.</div></div></div><div class="card list" style="margin-top:12px">${commentaryCards||'<div class="muted">No commentary leaves planted yet.</div>'}</div></details>
 <details open><summary><b>Public-Domain Bible Corpus Reader</b></summary><div class="notice"><b>Why this exists</b><div class="small">Use public-domain or properly licensed Bible texts. Imported sources remain separately identified so translations and commentary are never silently blended.</div></div><div class="actions"><button id="importBibleCorpus" class="primary">Import public-domain Bible text</button><button data-source-url="https://www.gutenberg.org/ebooks/30">Get KJV text</button><button data-source-url="https://www.gutenberg.org/ebooks/8300">Get Douay-Rheims text</button></div><div class="card list" style="margin-top:10px">${corpusRows||'<div class="muted">No searchable corpus imported yet. Download the plain-text KJV or Douay-Rheims and import it here.</div>'}</div><div class="split" style="margin-top:12px"><div class="card"><form id="bibleReaderForm" class="form"><label>Corpus<select id="readerCorpus">${corpora.map(c=>`<option value="${esc(c.id)}" ${c.id===state.bibleCorpusId?'selected':''}>${esc(c.translation||c.title)}</option>`).join('')}</select></label><label>Book<input id="readerBook" list="bibleBookNames" value="${esc(state.bibleBook)}" placeholder="Matthew"></label><datalist id="bibleBookNames">${books.map(b=>`<option value="${esc(b.canonical_name)}"></option><option value="${esc(b.douay_rheims_name)}"></option>`).join('')}</datalist><label>Chapter<input id="readerChapter" type="number" min="1" value="${esc(state.bibleChapter)}"></label><label class="row red-letter-toggle"><input id="readerRedToggle" type="checkbox" ${state.bibleRedLetters?'checked':''} style="width:auto;min-height:0"> <span>Show Jesus-word annotations in red</span></label><button class="primary">Load chapter</button></form><hr><form id="bibleSearchForm" class="form"><label>Search this corpus<input id="bibleSearchQuery" placeholder="e.g. John 8:12 or kingdom"></label><button>Search</button></form></div><div class="card"><div class="tag">READER / SEARCH RESULTS</div><div id="bibleReaderResults" class="bible-reader-results"><div class="muted">Choose an imported corpus and load a chapter or search.</div></div></div></div></details>
 <details><summary><b>Red-Letter Layer · Jesus’ Words</b></summary><div class="notice"><b>Annotation, not alteration</b><div class="small">${esc(atlas.red_letter||'Red-letter highlighting is source-tracked and toggleable. It does not modify scans or corpus text.')}</div></div><div class="split" style="margin-top:12px"><div class="card"><form id="redLetterForm" class="form"><label>Scripture verse reference<input id="redRef" required placeholder="e.g. John 8:12"></label><label>Source / authority used for the attribution<input id="redSource" required placeholder="e.g. user-owned edition, editorial source, scholarly note"></label><label>Confidence<select id="redConfidence"><option>HIGH</option><option>MEDIUM</option><option>DISPUTED</option><option>REVIEW_REQUIRED</option></select></label><label>Notes<textarea id="redNotes" placeholder="Why this whole verse is marked; dialogue boundary or textual caveats…"></textarea></label><button class="primary">Add red-letter annotation</button></form></div><div class="card list">${redRows||'<div class="muted">No red-letter annotations recorded yet. Arkforge will not guess them silently.</div>'}</div></div></details>
 <details><summary><b>Books · Names · Definitions (${books.length})</b></summary><div class="notice"><b>Name index</b><div class="small">Catholic canonical name + KJV naming + Douay-Rheims naming + original/traditional form + a concise meaning. Uncertain or traditional etymologies should stay labeled rather than being forced into certainty.</div></div><div class="table-wrap"><table class="atlas-table"><thead><tr><th>#</th><th>Book</th><th>KJV</th><th>Douay-Rheims</th><th>Original / traditional</th><th>Name meaning</th></tr></thead><tbody>${bookRows}</tbody></table></div></details>
 <details><summary><b>People + Peoples / Cultures</b></summary><div class="notice"><b>Human-first historical labeling</b><div class="small">Ancient peoples are described using historically appropriate peoples, polities, cultures, languages and regions. Modern racial categories are not projected backward unless a specific source and research question justify the comparison.</div></div><div class="split"><div><h3>Persons</h3><div class="card list">${personRows}</div></div><div><h3>Peoples / cultures</h3><div class="card list">${groupRows}</div></div></div></details>
 <details><summary><b>Places + Maps</b></summary><div class="notice"><b>Map evidence</b><div class="small">Coordinates are reference points. Site identification and ancient boundaries can vary by period; confidence and alternatives belong in the record.</div></div><div class="card list">${placeRows}</div></details>
 <details><summary><b>Things · Objects · Institutions · Daily Life</b></summary><div class="card list">${objectRows}</div></details>
 <details><summary><b>Timeline · People Along the Way</b></summary><div class="timeline">${timelineRows}</div></details>
 <details><summary><b>Source Registry · Research Shelf</b></summary><div class="notice"><b>Source triangulation</b><div class="small">Primary texts, Catholic teaching resources, academic/history/archaeology references, geographic datasets and lexicons should be kept distinct. Commentary should say which source supports which claim.</div></div><div class="card list">${sourceRows}</div></details>
 <details open><summary><b>Digital copy / reader attachments</b></summary><div class="card list">${attachments.map(a=>{const m=metaObj(a);const p=allProjects.find(x=>x.id===m.project_id);return `<div class="item"><div class="row"><div class="grow"><b>${esc(a.title)}</b><div class="small muted">${esc(m.filename||'managed document')} · SHA ${esc((m.sha256||'').slice(0,20))}${m.sha256?'…':''}</div></div>${p?`<button data-bible-open-project="${esc(m.project_id)}">Open digital copy</button>`:''}</div><div class="small muted">${esc(a.body||'User-supplied digital attachment')}</div></div>`}).join('')||'<div class="muted">No full digital copy attached yet.</div>'}</div></details>
 <details><summary><b>Page Notes (${notes.length})</b></summary><div class="split"><div class="card"><form id="bibleNoteForm" class="form"><label>Physical page number<input id="bNotePage" inputmode="numeric" placeholder="e.g. 742"></label><label>Scripture reference<input id="bNoteRef" placeholder="e.g. John 8:12"></label><label>Note type<select id="bNoteType"><option>study</option><option>prayer</option><option>cross-reference</option><option>history</option><option>language</option><option>personal reflection</option><option>church group</option></select></label><label>Note<textarea id="bNoteBody" required placeholder="Write the note attached to this page/reference…"></textarea></label><button class="primary">Save page note</button></form></div><div class="card list">${notes.map(n=>{const m=metaObj(n);return `<div class="item"><div class="row"><b class="grow">${pageLabel(m)} · ${esc(m.scripture_reference||'No scripture reference')}</b><span class="state NATIVE">${esc(m.note_type||'note')}</span></div><p>${esc(n.body)}</p><div class="small muted">${esc(n.updated_at)}</div><div class="actions"><button data-edit-record="${esc(n.id)}" data-type="bible_note" data-title="${esc(n.title)}" data-body="${esc(n.body)}" data-meta="${esc(n.meta_json||'{}')}">Edit</button><button data-archive-record="${esc(n.id)}" data-archived="0">Archive</button></div></div>`}).join('')||'<div class="muted">No page notes yet.</div>'}</div></div></details>
 <details><summary><b>Questions + Resolution Notes (${questions.length})</b></summary><div class="split"><div class="card"><form id="bibleQuestionForm" class="form"><label>Physical page<input id="bQPage" inputmode="numeric"></label><label>Scripture reference<input id="bQRef" placeholder="book chapter:verse"></label><label>Question title<input id="bQTitle" required placeholder="What are we trying to understand?"></label><label>Question / context<textarea id="bQBody" required></textarea></label><button class="primary">Add question</button></form></div><div class="card list">${questions.map(q=>{const m=metaObj(q),rr=resByQ[q.id]||[];return `<div class="item question-card"><div class="row"><div class="grow"><b>${esc(q.title)}</b><div class="small muted">${pageLabel(m)} · ${esc(m.scripture_reference||'no reference')}</div></div><span class="state ${rr.length?'NATIVE':'IMPORT_REQUIRED'}">${rr.length?'RESOLVED / NOTES':'OPEN'}</span></div><p>${esc(q.body)}</p>${rr.map(r=>`<div class="resolution-note"><b>Resolution note</b><p>${esc(r.body)}</p><div class="small muted">${esc(metaObj(r).source_or_reasoning||'')} · ${esc(r.updated_at)}</div></div>`).join('')}<div class="actions"><button data-resolve-question="${esc(q.id)}" data-q-page="${esc(m.page||'')}" data-q-ref="${esc(m.scripture_reference||'')}" data-q-title="${esc(q.title)}" class="primary">Add resolution note</button><button data-edit-record="${esc(q.id)}" data-type="bible_question" data-title="${esc(q.title)}" data-body="${esc(q.body)}" data-meta="${esc(q.meta_json||'{}')}">Edit question</button></div></div>`}).join('')||'<div class="muted">No questions yet.</div>'}</div></div></details>
 <details><summary><b>Church Group Book (${sessions.length} sessions)</b></summary><div class="notice"><b>Local-first group workbook</b><div class="small">Participant names, discussion, questions, prayer/support notes and resolutions stay in app-private storage unless you explicitly share, print or back up the workspace.</div></div><div class="split" style="margin-top:12px"><div class="card"><form id="churchSessionForm" class="form"><label>Date<input id="cgDate" type="date"></label><label>Church / group name<input id="cgGroup" placeholder="Small group / Bible study"></label><label>Facilitator<input id="cgFacilitator"></label><label>Topic / session title<input id="cgTopic" required></label><label>Scripture reference<input id="cgRef" placeholder="e.g. Matthew 5:1–12"></label><label>Physical page(s)<input id="cgPage" placeholder="e.g. 1280–1282"></label><label>Participants<textarea id="cgPeople" placeholder="Names or count; optional"></textarea></label><label>Questions / discussion<textarea id="cgDiscussion"></textarea></label><label>Resolution / understanding notes<textarea id="cgResolution"></textarea></label><label>Next steps<textarea id="cgNext"></textarea></label><label>Prayer / support notes<textarea id="cgPrayer"></textarea></label><button class="primary">Save group session</button></form></div><div class="card list">${sessions.map(s=>{const m=metaObj(s);return `<div class="item"><div class="row"><div class="grow"><b>${esc(s.title)}</b><div class="small muted">${esc(m.date||'undated')} · ${esc(m.group_name||'group')} · ${esc(m.scripture_reference||'')}</div></div><button data-share-session="${esc(s.id)}">Share</button></div><p>${esc(s.body)}</p><div class="small muted">Page(s): ${esc(m.page||'not set')} · Facilitator: ${esc(m.facilitator||'not set')}</div><div class="actions"><button data-edit-record="${esc(s.id)}" data-type="church_group_session" data-title="${esc(s.title)}" data-body="${esc(s.body)}" data-meta="${esc(s.meta_json||'{}')}">Edit</button><button data-archive-record="${esc(s.id)}" data-archived="0">Archive</button></div></div>`}).join('')||'<div class="muted">No church-group sessions yet.</div>'}</div></div><div class="actions"><button id="shareChurchBook">Share group-book summary</button><button id="printChurchBook">Print / save group book</button></div></details>`;
 const renderVerseList=(rows,label='')=>{const box=$('#bibleReaderResults');if(!box)return;box.innerHTML=(label?`<div class="reader-heading">${esc(label)}</div>`:'')+(rows||[]).map(v=>{const ref=`${v.book} ${v.chapter}:${v.verse}`,red=state.bibleRedLetters&&redByRef.has(bibleRefKey(ref));return `<div class="bible-verse ${red?'red-letter':''}"><div class="verse-ref">${esc(ref)}</div><div class="verse-text">${esc(v.text)}</div><button class="mini" data-reader-red-ref="${esc(ref)}">${redByRef.has(bibleRefKey(ref))?'Red-letter record':'Mark Jesus words'}</button></div>`}).join('')||'<div class="muted">No verses found. Check the corpus parser, book spelling, chapter, or search terms.</div>';box.querySelectorAll('[data-reader-red-ref]').forEach(b=>b.onclick=()=>{const ref=b.dataset.readerRedRef;if(redByRef.has(bibleRefKey(ref))){toast('A red-letter record already exists for '+ref);return}const authority=prompt('Source / authority for marking this verse as Jesus’ words');if(!authority)return;const note=prompt('Notes or dialogue-boundary caveat (optional)')||'';const rr=call('addRecord','bible_red_letter',ref,note||'Whole verse marked for the red-letter display layer.',JSON.stringify({scripture_reference:ref,source_authority:authority,confidence:'REVIEWED',scope:'whole_verse',display_only:true}));toast(rr.ok?'Red-letter annotation added':rr.error||'Could not add annotation',!rr.ok);if(rr.ok)renderBibleWorkspace()})};
 $('#backLibrary').onclick=()=>navigate('library');$('#printBibleWorkspace').onclick=()=>B.printCurrent();$('#printChurchBook').onclick=()=>B.printCurrent();
 $('#attachBibleDigital').onclick=()=>{state.pendingBibleAttach=true;B.importFile('library')};
 $('#importBibleCorpus').onclick=()=>B.importFile('bible_corpus');
 view.querySelectorAll('[data-source-url]').forEach(b=>b.onclick=()=>B.openUrl(b.dataset.sourceUrl));
 view.querySelectorAll('[data-select-corpus]').forEach(b=>b.onclick=()=>{state.bibleCorpusId=b.dataset.selectCorpus;toast('Reader corpus selected');renderBibleWorkspace()});
 view.querySelectorAll('[data-bible-map-place]').forEach(b=>b.onclick=()=>B.geo(Number(b.dataset.lat),Number(b.dataset.lon),b.dataset.bibleMapPlace));
 view.querySelectorAll('[data-bible-open-project]').forEach(b=>b.onclick=()=>B.runProject(b.dataset.bibleOpenProject));
 $('#plantSevenLeaves').onsubmit=e=>{e.preventDefault();const page=$('#leafPage').value.trim(),ref=$('#leafRef').value.trim();if(!ref)return;let made=0,failed=[];for(const l of leaves){const key=bibleLeafKey(page,ref,l.leaf);if(leafMap.has(key))continue;const body=`RESEARCH_REQUIRED\n\nStudy questions:\n${(l.questions||[]).map(q=>'• '+q).join('\n')}\n\nWorking commentary:\n\nSources / quotations / evidence:\n\nDisagreements / uncertainty:\n`;const meta={book_id:'faithbook-scripture',page,scripture_reference:ref,leaf:l.leaf,leaf_name:l.name,status:'RESEARCH_REQUIRED',required_source_classes:l.required_source_classes||[],source_ids:[],uncertainty:'OPEN',rule:l.rule||'',study_role:'research_curator'};const r=call('addRecord','bible_commentary_leaf',`${ref} · Leaf ${l.leaf} — ${l.name}`,body,JSON.stringify(meta));if(r.ok)made++;else failed.push(l.leaf)}toast(failed.length?`Planted ${made}; leaves ${failed.join(', ')} need review`:`Planted ${made} commentary leaves`,!!failed.length);if(made)renderBibleWorkspace()};
 view.querySelectorAll('[data-leaf-add-source]').forEach(b=>b.onclick=()=>{const rec=commentary.find(x=>x.id===b.dataset.leafAddSource);if(!rec)return;const m=metaObj(rec),cur=Array.isArray(m.source_ids)?m.source_ids:[];const ids=(prompt('Source IDs (comma-separated). Use IDs from the Source Registry.',cur.join(', '))||'').split(',').map(x=>x.trim()).filter(Boolean);m.source_ids=[...new Set(ids)];m.status=m.source_ids.length>=3?'SOURCE_TRIANGULATION_READY':'RESEARCH_REQUIRED';m.uncertainty=m.uncertainty||'OPEN';const rr=call('updateRecord',rec.id,rec.title,rec.body,JSON.stringify(m));toast(rr.ok?'Sources updated':rr.error||'Update failed',!rr.ok);if(rr.ok)renderBibleWorkspace()});
 const updatePublicStatus=()=>{const st=call('publicBibleStatus');const txt=$('#publicBibleStatusText'),bar=$('#publicBibleProgress');if(txt)txt.textContent=`${Number(st.installed_books||0)} / 73 canonical books cached · ${Number(st.bytes||0).toLocaleString()} bytes · ${st.state||''}${st.current?' · '+st.current:''}${st.last_error?' · '+st.last_error:''}`;if(bar)bar.style.width=`${Math.round(100*Number(st.installed_books||0)/73)}%`;return st};
 $('#installPublicBible').onclick=()=>{const r=call('installPublicBible');toast(r.message||r.error||'Scripture installer started',!r.ok);let tries=0;clearInterval(state.publicBiblePoll);state.publicBiblePoll=setInterval(()=>{tries++;const st=updatePublicStatus();if(st.complete||st.state==='ERROR'||tries>600){clearInterval(state.publicBiblePoll);if(st.complete)toast('All 73 canonical books are installed for offline reading.')}},1000)};
 $('#publicBibleSourceButton').onclick=()=>B.openUrl(publicSource.repository||'https://github.com/janvier-s/original-douay-rheims');
 const openPublicChapter=()=>{state.publicBibleSlug=$('#publicReaderBook').value;state.publicBibleChapter=Math.max(1,Number($('#publicReaderChapter').value)||1);state.publicBibleRedLetters=$('#publicReaderRed').checked;state.publicReaderMode=$('#publicReaderMode').value;state.publicReaderPerPage=Number($('#publicReaderPerPage').value)||8;state.publicReaderFont=Number($('#publicReaderFont').value)||20;state.publicReaderShowNumbers=$('#publicReaderNumbers').checked;saveBibleReaderPrefs();const r=call('publicBibleChapter',state.publicBibleSlug,String(state.publicBibleChapter));if(!r.ok){toast(r.error||'Could not open chapter',true);return}$('#publicReaderChapter').max=String(r.chapter_count||200);state.publicReaderPage=1;renderPublicBibleRows(r.verses||[],`${r.book} ${r.chapter}`,starter,redByRef,r.summary||'')};
 $('#publicBibleReaderForm').onsubmit=e=>{e.preventDefault();openPublicChapter()};
 $('#publicPrevChapter').onclick=()=>{const n=Math.max(1,(Number($('#publicReaderChapter').value)||1)-1);$('#publicReaderChapter').value=n;openPublicChapter()};
 $('#publicNextChapter').onclick=()=>{const n=(Number($('#publicReaderChapter').value)||1)+1;$('#publicReaderChapter').value=n;openPublicChapter()};
 $('#publicReaderRed').onchange=openPublicChapter;
 $('#publicReaderMode').onchange=openPublicChapter;
 $('#publicReaderPerPage').onchange=openPublicChapter;
 $('#publicReaderFont').onchange=openPublicChapter;
 $('#publicReaderNumbers').onchange=openPublicChapter;
 $('#publicReaderBook').onchange=()=>{state.publicBibleSlug=$('#publicReaderBook').value;const i=call('publicBibleBookInfo',state.publicBibleSlug);if(i.ok){$('#publicReaderChapter').max=String(i.chapter_count||1);if(Number($('#publicReaderChapter').value)>Number(i.chapter_count||1))$('#publicReaderChapter').value='1';toast(`${i.name} · ${i.chapter_count} chapters`)} };
 $('#publicBibleSearchForm').onsubmit=e=>{e.preventDefault();const q=$('#publicBibleSearchQuery').value.trim();if(!q)return;const r=call('publicBibleSearch',q,200);if(!r.ok){toast(r.error||'Search failed',true);return}renderPublicBibleRows(r.results||[],`Search · ${q}`,starter,redByRef,'')};
 if(requestedRef&&publicStatus.complete)setTimeout(openPublicChapter,30);
 $('#bibleReaderForm').onsubmit=e=>{e.preventDefault();state.bibleCorpusId=$('#readerCorpus').value;state.bibleBook=$('#readerBook').value.trim();state.bibleChapter=Number($('#readerChapter').value)||1;state.bibleRedLetters=$('#readerRedToggle').checked;if(!state.bibleCorpusId){toast('Import or select a corpus first',true);return}const r=call('bibleChapter',state.bibleCorpusId,state.bibleBook,String(state.bibleChapter));renderVerseList(r.verses||[],`${state.bibleBook} ${state.bibleChapter}`)};
 $('#readerRedToggle').onchange=()=>{state.bibleRedLetters=$('#readerRedToggle').checked;const r=state.bibleCorpusId?call('bibleChapter',state.bibleCorpusId,$('#readerBook').value.trim(),String(Number($('#readerChapter').value)||1)):{verses:[]};renderVerseList(r.verses||[],`${$('#readerBook').value.trim()} ${Number($('#readerChapter').value)||1}`)};
 $('#bibleSearchForm').onsubmit=e=>{e.preventDefault();const corpus=$('#readerCorpus').value,q=$('#bibleSearchQuery').value.trim();if(!corpus||!q){toast('Choose a corpus and enter a search',true);return}state.bibleCorpusId=corpus;const r=call('bibleSearch',corpus,q,200);renderVerseList(r.results||[],`Search · ${q}`)};
 $('#redLetterForm').onsubmit=e=>{e.preventDefault();const ref=$('#redRef').value.trim(),src=$('#redSource').value.trim(),confidence=$('#redConfidence').value,note=$('#redNotes').value.trim();if(!ref||!src)return;if(redByRef.has(bibleRefKey(ref))){toast('That reference already has a red-letter record. Edit the existing record instead.',true);return}const r=call('addRecord','bible_red_letter',ref,note||'Whole verse marked for the red-letter display layer.',JSON.stringify({scripture_reference:ref,source_authority:src,confidence,scope:'whole_verse',display_only:true}));toast(r.ok?'Red-letter annotation saved':r.error||'Save failed',!r.ok);if(r.ok)renderBibleWorkspace()};
 $('#bibleNoteForm').onsubmit=e=>{e.preventDefault();const page=$('#bNotePage').value.trim(),ref=$('#bNoteRef').value.trim(),type=$('#bNoteType').value,body=$('#bNoteBody').value.trim();if(!body)return;const r=call('addRecord','bible_note',`${page?'Page '+page+' · ':''}${ref||type}`,body,JSON.stringify({book_id:'library-arkforge-study-bible',page,scripture_reference:ref,note_type:type}));toast(r.ok?'Page note saved':r.error||'Save failed',!r.ok);if(r.ok)renderBibleWorkspace()};
 $('#bibleQuestionForm').onsubmit=e=>{e.preventDefault();const page=$('#bQPage').value.trim(),ref=$('#bQRef').value.trim(),title=$('#bQTitle').value.trim(),body=$('#bQBody').value.trim();const r=call('addRecord','bible_question',title,body,JSON.stringify({book_id:'library-arkforge-study-bible',page,scripture_reference:ref,status:'OPEN'}));toast(r.ok?'Question added':r.error||'Save failed',!r.ok);if(r.ok)renderBibleWorkspace()};
 view.querySelectorAll('[data-resolve-question]').forEach(b=>b.onclick=()=>{const answer=prompt('Resolution / answer note');if(!answer)return;const reasoning=prompt('Source, reasoning, or follow-up reference (optional)')||'';const r=call('addRecord','bible_resolution',`Resolution · ${b.dataset.qTitle}`,answer,JSON.stringify({book_id:'library-arkforge-study-bible',question_id:b.dataset.resolveQuestion,page:b.dataset.qPage||'',scripture_reference:b.dataset.qRef||'',source_or_reasoning:reasoning,status:'RESOLUTION_NOTE'}));toast(r.ok?'Resolution note saved':r.error||'Save failed',!r.ok);if(r.ok)renderBibleWorkspace()});
 $('#churchSessionForm').onsubmit=e=>{e.preventDefault();const m={book_id:'library-arkforge-study-bible',date:$('#cgDate').value,group_name:$('#cgGroup').value.trim(),facilitator:$('#cgFacilitator').value.trim(),topic:$('#cgTopic').value.trim(),scripture_reference:$('#cgRef').value.trim(),page:$('#cgPage').value.trim(),participants:$('#cgPeople').value.trim(),discussion:$('#cgDiscussion').value.trim(),resolution_notes:$('#cgResolution').value.trim(),next_steps:$('#cgNext').value.trim(),prayer_support_notes:$('#cgPrayer').value.trim()};const body=`Scripture: ${m.scripture_reference||'not set'}\nPage(s): ${m.page||'not set'}\n\nQuestions / discussion:\n${m.discussion||'—'}\n\nResolution / understanding:\n${m.resolution_notes||'—'}\n\nNext steps:\n${m.next_steps||'—'}\n\nPrayer / support notes:\n${m.prayer_support_notes||'—'}\n\nParticipants:\n${m.participants||'—'}`;const r=call('addRecord','church_group_session',m.topic||'Church group session',body,JSON.stringify(m));toast(r.ok?'Church group session saved':r.error||'Save failed',!r.ok);if(r.ok)renderBibleWorkspace()};
 const sessMap={};for(const ss of sessions)sessMap[ss.id]=ss;view.querySelectorAll('[data-share-session]').forEach(b=>b.onclick=()=>{const ss=sessMap[b.dataset.shareSession];if(!ss)return;const m=metaObj(ss);B.shareText(`Church Group Book · ${ss.title}`,`${ss.title}\nDate: ${m.date||''}\nGroup: ${m.group_name||''}\nFacilitator: ${m.facilitator||''}\nReference: ${m.scripture_reference||''}\nPage(s): ${m.page||''}\n\n${ss.body}`)});
 $('#shareChurchBook').onclick=()=>{const txt=sessions.map(ss=>{const m=metaObj(ss);return `${ss.title}\n${m.date||''} · ${m.group_name||''} · ${m.scripture_reference||''} · page ${m.page||''}\n${ss.body}`}).join('\n\n--------------------\n\n');B.shareText('HeritageFaith Church Group Book',txt||'No sessions recorded yet.')};
