function renderProduction(){view.innerHTML=sectionTitle('Production','Jobs, travelers, revisions, lots, tests and release notes remain append-preserving evidence. Cantus records each create/update/archive action.')+`<div class="actions">${actionButton('New production record','new-production',true)}</div>`+recordList('production');wireActions();wireRecordButtons();}
function renderEngineering(){view.innerHTML=sectionTitle('Engineering','Digital lifecycle workbench. Auto Finish may validate digital files and build release scaffolds, but cannot promote a physical gate without real evidence.')+`<div class="notice"><b>Lifecycle</b><div class="small mono">idea → requirements → design → blueprint → materials → constraints → prototype → test → revision → manufacturing package → release → archive</div></div><div class="grid" style="margin-top:12px">${RECORD_TOOLS.filter(x=>['artifact','design','lifecycle','failures','provenance','materials','physics','constraints','patents','civis'].includes(x[0])).map(([id,label,desc])=>`<div class="card clickable" data-tool="${id}"><div class="tag">ENGINEERING</div><h3>${esc(label)}</h3><div class="small muted">${esc(desc)}</div></div>`).join('')}</div>`;view.querySelectorAll('[data-tool]').forEach(x=>x.addEventListener('click',()=>navigate(x.dataset.tool)));wireActions();}
function renderGarden(){const p=call('projects');const gardens=(p.projects||[]).filter(x=>x.family==='garden');view.innerHTML=sectionTitle('Garden Immortals','The standalone runtime preserves imported Garden packages without pretending the bundled Field Lab is the historical full game. Residents in the Field Lab can rest and refuse continuous work.')+`<div class="actions">${actionButton('Install / reset R10 Field Lab','install-garden-lab',true)}${actionButton('Import surviving Garden package','import-garden')}</div><div class="notice"><b>Rest & autonomy</b><div class="small">Rest, sleep, free time and refusal are normal world states. This policy is part of the R10 Garden runtime and is not treated as a failure condition.</div></div><h2>Garden branches</h2>${projectCards(gardens)}`;wireActions();wireProjectButtons();}
function renderFarm(){view.innerHTML=sectionTitle('Farm Time','Local farm tasks, crop/animal observations, schedules and experiments. No network is required.')+`<div class="actions">${actionButton('New Farm Time record','new-farm',true)}</div>`+recordList('farm');wireActions();wireRecordButtons();}

function renderCantus(){const r=call('cantus',300);const v=call('verifyCantus');view.innerHTML=sectionTitle('Cantus Logs','Every native mutation is recorded in an append-only SQLite event ledger. Each event includes the previous hash and its own SHA-256 chain hash.')+`<div class="grid"><div class="card"><div class="tag">CHAIN</div><div class="metric ${v.ok?'good':'bad'}">${v.ok?'VERIFIED':'REVIEW'}</div><div class="small muted">${v.events||0} events</div></div><div class="card"><div class="tag">HEAD HASH</div><div class="small mono">${esc((v.head||'').slice(0,32))}${v.head?'…':''}</div></div></div><div class="actions">${actionButton('Verify again','verify-cantus',true)}${actionButton('Share log summary','share-cantus')}</div><h2>Recent events</h2><div class="card list">${(r.logs||[]).map(x=>`<div class="item"><div class="row"><b>#${x.seq} · ${esc(x.module)} / ${esc(x.action)}</b><span class="state ${x.status==='PASS'?'NATIVE':''}">${esc(x.status)}</span></div><div class="small muted">${esc(x.ts)}</div><div>${esc(x.detail)}</div><div class="small mono muted">${esc((x.chain_hash||'').slice(0,24))}…</div></div>`).join('')}</div>`;wireActions();}

